SELECT e.thread_id,e.sequence,p.agent_id AS "agent_id!" FROM chat_activity e JOIN chat_participants p ON p.thread_id=e.thread_id JOIN agents a ON a.id=p.agent_id WHERE a.deployment_mode='sidecar' AND a.deleted_at IS NULL AND (p.active OR e.kind='participant.left') AND NOT EXISTS(SELECT 1 FROM sidecar_bridge_receipts b WHERE b.thread_id=e.thread_id AND b.sequence=e.sequence AND b.agent_id=p.agent_id) ORDER BY e.created_at,e.thread_id,e.sequence LIMIT 50;
